  async function mutate(path,body={}){return auth(path,{method:'POST',headers:{'content-type':'application/json',accept:'application/json'},body:JSON.stringify(body)})}
  async function entityTargets(kind,entityId){return auth('/impersonation/targets/'+(kind==='AGENT'?'agent':'company')+'/'+encodeURIComponent(entityId))}
  function retirementPath(kind,entityId,action){return '/retirement/'+(kind==='AGENT'?'agent':'company')+'/'+encodeURIComponent(entityId)+'/'+action}
  function entityTargetLabel(u){return [txt(u?.display_name)||txt(u?.name)||'Пользователь',txt(u?.login_name)||txt(u?.login)].filter(Boolean).join(' · ')}
  async function openEntityOptions(kind,entityId,displayName){
    if(!entityId)return notice(kind==='AGENT'?'Agent Person ID отсутствует.':'Client ID отсутствует.','Опции');
    const m=modal(displayName||entityId),identity=el('div','ca-id',entityId),status=el('div','ca-role-note','Проверяю доступ к кабинету…'),targetHost=el('div','ca-form'),actions=el('div','ca-modal-actions'),close=el('button','ca-btn','Закрыть'),enter=el('button','ca-primary','Войти в кабинет'),remove=el('button','ca-btn ca-danger',kind==='AGENT'?'Удалить агента':'Удалить компанию');
    remove.dataset.ronaDangerAction='entity-delete';
    remove.style.setProperty('border-color','rgba(255,92,106,.82)','important');
    remove.style.setProperty('background','linear-gradient(135deg,rgba(209,30,48,.99),rgba(132,14,31,.99))','important');
    remove.style.setProperty('color','#fff','important');
    remove.style.setProperty('box-shadow','0 0 18px rgba(239,49,70,.18),inset 0 1px 0 rgba(255,255,255,.07)','important');
    close.type=enter.type=remove.type='button';enter.disabled=true;close.onclick=m.close;actions.append(close,enter,remove);m.box.append(identity,status,targetHost,actions);
    let targetInfo=null,targetSelect=null;
    try{
      targetInfo=await entityTargets(kind,entityId);
      const usersList=Array.isArray(targetInfo?.users)?targetInfo.users:[];
      if(kind==='COMPANY'&&usersList.length>1){
        targetSelect=el('select');for(const u of usersList)targetSelect.append(new Option(entityTargetLabel(u),txt(u.portal_user_id||u.id)));
        targetHost.append(label('Пользователь кабинета',targetSelect));status.textContent='Выберите пользователя. Доступ останется жёстко ограничен этой компанией.';enter.disabled=false;
      }else if(usersList.length===1&&targetInfo?.canImpersonate!==false){
        targetSelect=el('select');const u=usersList[0];targetSelect.append(new Option(entityTargetLabel(u),txt(u.portal_user_id||u.id)));targetSelect.hidden=true;targetHost.append(targetSelect);status.textContent=kind==='AGENT'?'Вход будет выполнен с полномочиями этого Agent Person.':'Вход будет выполнен с полномочиями клиента только в контексте этой компании.';enter.disabled=false;
      }else if(targetInfo?.subjectMode==='ADMIN_ENTITY'&&targetInfo?.canImpersonate!==false){
        status.textContent=kind==='AGENT'
          ?'Открытие кабинета агента в административном режиме просмотра. Portal-учётная запись агента для этого не требуется.'
          :'Открытие кабинета в административном режиме просмотра. Portal-учётная запись клиента для этого не требуется.';
        enter.disabled=false;
      }else{
        status.textContent=targetInfo?.disabledReason==='AGENT_PORTAL_USER_INVARIANT_VIOLATION'?'Вход закрыт: нарушена уникальность активной учётной записи Agent Person.':'Для этой сущности нет активной Portal-учётной записи.';
        enter.disabled=true;
      }
    }catch(e){status.textContent=errorText(e?.code||e?.message);enter.disabled=true}

    enter.onclick=async()=>{
      if(enter.disabled)return;
      const targetPortalUserId=txt(targetSelect?.value);
      enter.disabled=true;remove.disabled=true;
      status.textContent='Открываю кабинет…';
      try{
        const started=await auth('/impersonation/start',{method:'POST',headers:{'content-type':'application/json',accept:'application/json','x-rona-admin-handoff':'clients-agents-v8'},body:JSON.stringify({kind,entityId,targetPortalUserId:targetPortalUserId||null})});
        const sessionId=txt(started?.impersonation?.id);
        const targetPath=txt(started?.targetPath);
        if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(sessionId)||!['/portal/client','/portal/agent'].includes(targetPath)){
          throw Object.assign(new Error('IMPERSONATION_START_FAILED'),{code:'IMPERSONATION_START_FAILED'});
        }
        window.location.assign(targetPath+'?impSession='+encodeURIComponent(sessionId));
      }catch(e){
        status.textContent=errorText(e?.code||e?.message);
        enter.disabled=false;remove.disabled=false;
      }
    };

    remove.onclick=async()=>{
      remove.disabled=true;enter.disabled=true;
      try{
        const preflight=await mutate(retirementPath(kind,entityId,'preview'),{});
        const p=preflight?.preview||{},impact=p?.impact||{},archive=p?.archive||{};
        const impactSummary=kind==='AGENT'
          ?'Будут закрыты активные доступы агента и назначения: '+Number(impact.agentBindings||0)+' доступ(ов), '+Number(impact.companyAssignments||0)+' назначение(й).'
          :'Будут закрыты доступы только этой компании: '+Number(impact.clientBindings||0)+' пользовательских привязок, '+Number(impact.agentAssignments||0)+' назначение(й) агента.';
        const archiveSummary=' История сохраняется без удаления бизнес-данных.';
        const ok=await confirmBox((kind==='AGENT'?'Удалить агента «':'Удалить компанию «')+(displayName||entityId)+'» из активного контура? '+impactSummary+archiveSummary,kind==='AGENT'?'Подтверждение удаления агента':'Подтверждение удаления компании');
        if(!ok)return;
        await mutate(retirementPath(kind,entityId,'execute'),{operationId:preflight.operationId,confirmationNonce:preflight.confirmationNonce});
        m.close();S.view=kind==='AGENT'?'agents':'companies';await refresh();
        await notice(kind==='AGENT'?'Агент удалён из активного контура. История сохранена.':'Компания удалена из активного контура. История сохранена.',kind==='AGENT'?'Агент удалён':'Компания удалена');
      }catch(e){await notice(errorText(e?.code||e?.message),kind==='AGENT'?'Удаление агента':'Удаление компании')}
      finally{if(document.body.contains(m.back)){remove.disabled=false;enter.disabled=!(targetInfo?.canImpersonate&&targetSelect)}}
    };
  }
