  function contractStatus(id,c){const g=gates().find(x=>txt(x?.contractId||x?.contract_id||x?.id)===id)||{};let ready=false;try{if(typeof window.signedContractGateAllows==='function')ready=window.signedContractGateAllows(id)===true}catch(_){ }if(!ready)ready=(g?.bilateralSignedConfirmed===true&&g?.serverConfirmed!==false)||(c?.bilateralSignedConfirmed===true&&c?.serverConfirmed!==false)||(c?.signedContractConfirmed===true)||(c?.signed_contract_confirmed===true);const documentId=txt(g?.documentId||g?.signedDocumentId||g?.signed_document_id||c?.documentId||c?.signedDocumentId||c?.signed_document_id||c?.currentDocumentId||c?.current_document_id);const attached=ready||!!documentId||g?.documentAttached===true||g?.signedPdfAttached===true||c?.documentAttached===true||c?.signedPdfAttached===true;return{ready,attached,documentId}}
